contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address spender, uint256 amount, uint256 prevAllowance) public {
        // set up an arbitrary previous allowance
        c.approve(spender, prevAllowance); if (__ESBMC_reverted()) return;
        uint256 before = c.allowance(address(this), spender); if (__ESBMC_reverted()) return;
        // the deciding call: a fresh approve must overwrite, not add
        c.approve(spender, amount); if (__ESBMC_reverted()) return;
        uint256 afterAllowance = c.allowance(address(this), spender); if (__ESBMC_reverted()) return;
        assert(afterAllowance == amount && (before == prevAllowance));
    }
    receive() external payable {}
}

