pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {GSPFunding} from "../src/GSPFunding.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    GSPFunding c;

    function setUp() public {
        c = new GSPFunding();
    }

    function _run(address spender, uint256 amount, uint256 prevAllowance) internal {
        try c.approve(spender, prevAllowance) {} catch { return; }
        uint256 before;
        try c.allowance(address(this), spender) returns (uint256 __r) { before = __r; } catch { return; }
        try c.approve(spender, amount) {} catch { return; }
        uint256 afterAllowance;
        try c.allowance(address(this), spender) returns (uint256 __r) { afterAllowance = __r; } catch { return; }
        assertTrue(afterAllowance == amount && (before == prevAllowance));
    }

    function testFuzz_run(address spender, uint256 amount, uint256 prevAllowance) public {
        vm.assume(spender.code.length == 0 && uint160(spender) > 0xffff && spender != address(this) && spender != address(c) && spender != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && spender != 0x000000000000000000636F6e736F6c652e6c6f67 && spender != 0x4e59b44847b379578588920cA78FbF26c0B4956C && spender != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(spender, amount, prevAllowance);
    }

    receive() external payable {}
}
